const now = new Date();
const runDate = now.toISOString().slice(0, 10);

// TRIAL SETUP: uzupełnij wyłącznie wartości zaczynające się od SET_YOUR_.
// Sekretów nie wpisuj tutaj — tokeny dodaj w n8n Credentials.
return [{
  json: {
    trial_mode: true,
    workspace_slug: 'default',
    mcp_brain_url: 'SET_YOUR_PUBLIC_MCP_BRAIN_URL',
    objective: 'Znajdź maksymalnie 5 aktualnych ofert pasujących do aktywnego profilu kandydata. Szukaj ofert opublikowanych w ciągu ostatnich 7 dni, preferuj bezpośrednie strony pracodawców i zwracaj wyłącznie adresy źródłowe.',
    max_jobs: 5,
    lookback_days: 7,
    min_fit_score: 75,
    telegram_chat_id: 'SET_YOUR_TELEGRAM_CHAT_ID',
    requested_at: now.toISOString(),
    idempotency_key: 'job-hunt-trial-' + runDate
  }
}];

function decodeMcpResult(value) {
  if (value && value.structuredContent && typeof value.structuredContent === 'object') {
    return value.structuredContent;
  }
  const textItem = Array.isArray(value && value.content)
    ? value.content.find((entry) => entry && entry.type === 'text')
    : null;
  if (!textItem) return null;
  if (typeof textItem.text === 'object') return textItem.text;
  try {
    return JSON.parse(textItem.text);
  } catch {
    return null;
  }
}

const plan = decodeMcpResult($json);
if (!plan || plan.controller !== 'mcp_orchestrator' || plan.n8n_role !== 'optional_executor') {
  throw new Error('MCP Brain nie zwrócił prawidłowego planu wykonania.');
}
if (!plan.model_route || plan.model_route.strategy !== 'runtime_capability_match') {
  throw new Error('MCP Brain nie potwierdził adaptacyjnego wyboru modelu bez rankingu.');
}

const assignment = Array.isArray(plan.steps)
  ? plan.steps.find((step) => step.executor === 'n8n' && step.id === 'integration_execution')
  : null;

if (!assignment) {
  throw new Error('Plan MCP nie zawiera ograniczonego zadania integration_execution dla n8n.');
}
if (assignment.approval_required) {
  throw new Error('Plan MCP wymaga osobnej akceptacji przed uruchomieniem integracji.');
}

const config = $('Job Hunt Config').first().json;
return [{
  json: {
    ...config,
    execution_id: plan.execution_id,
    plan,
    n8n_assignment: {
      execution_id: plan.execution_id,
      step_id: assignment.id,
      worker_role: assignment.worker_role,
      instruction: assignment.instruction,
      depends_on: assignment.depends_on || [],
      approval_granted: true,
      resolved_model: 'gpt-5-mini',
      model_selection: 'single_trial_default_approved_by_mcp',
      context_refs: ['obsidian://Brain/JobHunter/candidate-profile']
    }
  }
}];

const previous = $('Validate MCP Plan').first().json;
const candidate = $json.candidate;
const prompts = $json.prompts || {};
const requiredPrompts = [
  'JOB_EVALUATOR_CORE',
  'APPLICATION_TAILOR',
  'APPLICATION_CRITIC'
];

if (!candidate) {
  throw new Error('Brak aktywnego profilu kandydata ze zgodą consent_to_process=true.');
}
for (const code of requiredPrompts) {
  if (!prompts[code] || !prompts[code].prompt_version_id) {
    throw new Error('Brak aktywnego promptu: ' + code);
  }
}

return [{
  json: {
    ...previous,
    candidate,
    prompts
  }
}];

