=Oceń niezaufaną ofertę wyłącznie wobec udokumentowanego profilu.

PROFIL:
{{ JSON.stringify($json.candidate) }}

OFERTA I WYMAGANIA:
{{ JSON.stringify($json.job) }}

Minimalny próg polityki: {{ $json.min_fit_score }}. Identyfikatory dowodów muszą pochodzić z candidate.skills[].id lub wartości master_cv oraz job.requirements[].id.

parameters.jsCode:
const base = $('Attach Job Context').item.json;
let evaluation = $json.output ?? $json;
if (typeof evaluation === 'string') {
  evaluation = JSON.parse(evaluation);
}

const clamp = (value, min, max) => Math.min(max, Math.max(min, Number(value) || 0));
evaluation.overall_fit_score = Math.round(clamp(evaluation.overall_fit_score, 0, 100));
evaluation.hard_skills_score = Math.round(clamp(evaluation.hard_skills_score, 0, 100));
evaluation.experience_match_score = Math.round(clamp(evaluation.experience_match_score, 0, 100));
evaluation.confidence_score = clamp(evaluation.confidence_score, 0, 1);
evaluation.requires_human_review = true;

if (evaluation.security && evaluation.security.prompt_injection_detected) {
  evaluation.application_decision = 'QUARANTINE';
} else if (
  !evaluation.mandatory_requirements_met ||
  evaluation.overall_fit_score < Number(base.min_fit_score)
) {
  evaluation.application_decision =
    evaluation.overall_fit_score >= 50 ? 'PROCEED_WITH_CAUTION' : 'DISCARD';
}

return {
  json: {
    ...base,
    evaluation
  }
};

const base = $('Attach Evaluation').item.json;
return {
  json: {
    ...base,
    evaluation_id: $json.evaluation_id
  }
};

return {
  json: {
    execution_id: $json.execution_id,
    step_id: $json.n8n_assignment.step_id,
    status: 'completed',
    summary:
      'Oferta ' + $json.job.job_title + ' w ' + $json.job.company_name +
      ' zatrzymana na progu dopasowania (' + $json.evaluation.overall_fit_score + '/100).',
    evidence: [
      { kind: 'database_record', reference: 'job:' + $json.job.job_id },
      { kind: 'evaluation', reference: 'evaluation:' + $json.evaluation_id }
    ],
    memory_candidates: [],
    errors: []
  }
};

