Nie dodawaj żadnego faktu bez profile_evidence_id.

parameters.jsCode:
const base = $('Attach Evaluation ID').item.json;
let artifact = $json.output ?? $json;
if (typeof artifact === 'string') artifact = JSON.parse(artifact);

function strictHtml(value) {
  const raw = String(value ?? '').replace(/\u0000/g, '');
  const cleaned = raw.replace(/<[^>]*>/g, (tag) => {
    const match = tag.match(/^<\s*(\/?)\s*(h1|h2|p|ul|li|strong)\s*>$/i);
    if (!match) return '';
    return '<' + (match[1] ? '/' : '') + match[2].toLowerCase() + '>';
  });
  return { raw, cleaned };
}
function plain(value, maxLength) {
  return String(value ?? '').replace(/\u0000/g, '').trim().slice(0, maxLength);
}

const resume = strictHtml(artifact.tailored_resume_html);
const email = strictHtml(artifact.email_body_html);
artifact.tailored_resume_html = resume.cleaned;
artifact.email_body_html = email.cleaned;
artifact.tailored_resume_text = plain(artifact.tailored_resume_text, 30000);
artifact.cover_letter_text = plain(artifact.cover_letter_text, 10000);
artifact.email_subject = plain(artifact.email_subject, 200);
artifact.modifications_summary = plain(artifact.modifications_summary, 3000);
artifact.sanitization_changes = {
  resume_html_changed: resume.raw !== resume.cleaned,
  email_html_changed: email.raw !== email.cleaned
};

if (
  artifact.tailored_resume_html.length < 200 ||
  artifact.tailored_resume_text.length < 200 ||
  artifact.cover_letter_text.length < 200
) {
  throw new Error('Artefakt aplikacyjny jest niepełny po sanitizacji.');
}

return {
  json: {
    ...base,
    artifact
  }
};

