parameters.jsCode:
const base = $('Sanitize Application Artifact').item.json;
let critic = $json.output ?? $json;
if (typeof critic === 'string') critic = JSON.parse(critic);
return {
  json: {
    ...base,
    critic
  }
};

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}
const base = $('Attach Critic Verdict').item.json;
return {
  json: {
    ...base,
    telegram_text:
      '<b>🛑 Critic zatrzymał pakiet</b>\n' +
      escapeHtml(base.job.job_title) + ' — ' + escapeHtml(base.job.company_name) + '\n' +
      'Werdykt: <b>' + escapeHtml(base.critic.verdict) + '</b>\n' +
      escapeHtml(base.critic.summary)
  }
};

const base = $('Attach Critic Verdict').item.json;
return {
  json: {
    ...base,
    artifact_id: $json.artifact_id,
    artifact_version: $json.artifact_version,
    review_id: $json.review_id,
    approval_token: $json.approval_token
  }
};

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}
const job = $json.job;
const evaluation = $json.evaluation;
const strengths = (evaluation.strengths || []).slice(0, 3);
const gaps = (evaluation.gaps || []).slice(0, 2);
const salary = job.salary_raw || 'brak widełek';
const lines = [
  '<b>🎯 ' + escapeHtml(job.job_title) + '</b>',
  escapeHtml(job.company_name) + ' · ' + escapeHtml(job.location || 'lokalizacja niepodana'),
  '💰 ' + escapeHtml(salary),
  '',
  '<b>📊 Dopasowanie: ' + evaluation.overall_fit_score + '%</b> (hard skills: ' + evaluation.hard_skills_score + '%)',
  '',
  '<b>Atuty</b>',
  ...(strengths.length ? strengths.map((value) => '• ' + escapeHtml(value)) : ['• brak']),
  '',
  '<b>Luki</b>',
  ...(gaps.length ? gaps.map((value) => '• ' + escapeHtml(value)) : ['• brak krytycznych']),
  '',
  '<b>Rekomendacja</b>',
  escapeHtml(evaluation.tailoring_recommendation || evaluation.strategic_reasoning),
  '',
  'Pakiet przeszedł niezależny Critic. Zatwierdzenie nie wysyła aplikacji automatycznie — przekazuje decyzję do MCP.'
];

if (!/^[a-f0-9]{60}$/.test(String($json.approval_token))) {
  throw new Error('Nieprawidłowy jednorazowy token HITL.');
}

return {
  json: {
    ...$json,
    telegram_text: lines.join('\n')
  }
};

// To nie jest sekret. Wpisz liczbowy Telegram User ID operatora.
const allowedUserId = 'SET_YOUR_TELEGRAM_USER_ID';
return { json: { ...$json, _allowed_user_id: allowedUserId } };

const callback = $json.callback_query;
if (!callback || !callback.id || !callback.data) {
  throw new Error('Brak callback_query w aktualizacji Telegram.');
}

const allowedUserId = String($json._allowed_user_id || '');
const actualUserId = String(callback.from && callback.from.id ? callback.from.id : '');
if (!/^\d+$/.test(allowedUserId) || actualUserId !== allowedUserId) {
  throw new Error('Nieautoryzowany użytkownik Telegram albo nieuzupełniony identyfikator operatora.');
}

const match = String(callback.data).match(/^([ARC]):([a-f0-9]{60})$/);
if (!match) {
  throw new Error('Nieprawidłowy lub przeterminowany format decyzji HITL.');
}

const decisions = {
  A: 'APPROVED',
  R: 'REJECTED',
  C: 'MODIFIED'
};

return {
  json: {
    decision: decisions[match[1]],
    approval_token: match[2],
    query_id: callback.id,
    reviewer_ref: 'telegram:' + actualUserId,
    telegram_message_id: String(callback.message && callback.message.message_id ? callback.message.message_id : '')
  }
};
